from collections import Counter,defaultdict,deque

def get_comps(g):
 H,W=len(g),len(g[0]); seen=set(); out=[]
 for r in range(H):
  for c in range(W):
   col=g[r][c]
   if (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   for x,y in q:
    cells.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<H and 0<=b<W and g[a][b]==col and (a,b) not in seen:
      seen.add((a,b));q.append((a,b))
   out.append({'color':col,'cells':cells,'min':(min(x for x,y in cells),min(y for x,y in cells))})
 return out

def sig(cells, dihedral=True):
 pts=list(cells)
 forms=[]
 for rot in range(4):
  p=[]
  for x,y in pts:
   if rot==0:a,b=x,y
   elif rot==1:a,b=y,-x
   elif rot==2:a,b=-x,-y
   else:a,b=-y,x
   p.append((a,b))
  for refl in (False,True) if dihedral else (False,):
   pp=[(a,-b if refl else b) for a,b in p]
   m1=min(a for a,b in pp);m2=min(b for a,b in pp)
   forms.append(tuple(sorted((a-m1,b-m2) for a,b in pp)))
 return min(forms)

